import re

from moler.exceptions import ParsingDone

from ta_moler.cmd.emssim.genericemssim import GenericEMSSIMCommand


class CertCmpKeyUpdate(GenericEMSSIMCommand):
    """Certcmpkeyupdate command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        Certcmpkeyupdate command.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(CertCmpKeyUpdate, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)

        self.start_parsing = False

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        return "cert_cmp_key_update"

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_line_start_parsing(line)
                self._parse_line_start_parsing_params(line)
                self._parse_line_params(line)
                self._parse_line_configuration_line(line)
                self._parse_line_end_parsing(line)
            except ParsingDone:
                pass
        return super(CertCmpKeyUpdate, self).on_new_line(line, is_full_line)

    _re_start_parsing = re.compile(r"-{10,}", re.I)

    def _parse_line_start_parsing(self, line):
        if not self.start_parsing and self._regex_helper.search_compiled(CertCmpKeyUpdate._re_start_parsing, line):
            self.start_parsing = True
            raise ParsingDone

    _re_start_parsing_params = re.compile(r"\|Parameters:", re.I)

    def _parse_line_start_parsing_params(self, line):
        if self.start_parsing and self._regex_helper.search_compiled(CertCmpKeyUpdate._re_start_parsing_params, line):
            self.current_ret["Parameters"] = {}
            raise ParsingDone

    _re_params = re.compile(r"\|\s+(?P<PARAM>.*)\s=>\s(?P<VALUE>.*)", re.I)

    def _parse_line_params(self, line):
        if self.start_parsing and self._regex_helper.search_compiled(CertCmpKeyUpdate._re_params, line):
            parameter = self._regex_helper.group("PARAM")
            value = self._regex_helper.group("VALUE")
            self.current_ret["Parameters"][parameter] = value
            raise ParsingDone

    _re_configuration_line = re.compile(r"\|(?P<ATTR>.*):(\s+(?P<VALUE>.*))*", re.I)

    def _parse_line_configuration_line(self, line):
        if self.start_parsing and self._regex_helper.search_compiled(CertCmpKeyUpdate._re_configuration_line, line):
            self.current_ret[self._regex_helper.group("ATTR")] = self._regex_helper.group("VALUE")
            raise ParsingDone

    def _parse_line_end_parsing(self, line):
        if self.start_parsing and self._regex_helper.search_compiled(CertCmpKeyUpdate._re_start_parsing, line):
            self.set_result(self.current_ret)
            raise ParsingDone


